{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const unresolved = issues.filter((i) => i.status === "unresolved");
  const out = [];
  for (const i of unresolved) {
    const { events } = await sdk.sentry.listIssueEvents({ issueId: i.id });
    out.push({ shortId: i.shortId, count: i.count, eventCount: events.length });
  }
  return out;
}"}

