{"code": "export async function main(input: unknown) {
  const ids = ["JOBS-1","JOBS-2","JOBS-3","JOBS-4","JOBS-5","JOBS-6","JOBS-7","JOBS-8","JOBS-9","JOBS-B"];
  const out: Record<string, unknown> = {};
  for (const id of ids) {
    const r = await sdk.linear.searchIssues({ query: `[Sentry] ${id}` });
    out[id] = r.issues.map((i) => ({ identifier: i.identifier, title: i.title, state: i.state }));
  }
  return out;
}"}

{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const targets = issues.filter((i) => i.status === "unresolved");

  const created: { shortId: string; title: string; description: string; result: unknown }[] = [];
  for (const issue of targets) {
    const title = `[Sentry] ${issue.shortId}`;
    const res = await sdk.linear.createIssue({ title, description: issue.culprit });
    created.push({ shortId: issue.shortId, title, description: issue.culprit, result: res });
  }
  return { planned: created.length, created };
}"}

